command:
cat > /etc/nginx/sites-available/fleet-tls.conf <<'EOF'
server {
    listen 8443 ssl;
    listen [::]:8443 ssl;
    server_name node2;

    ssl_certificate     /etc/ssl/fleet/node2.crt;
    ssl_certificate_key /etc/ssl/fleet/node2.key;

    root /var/www/html;
    index index.html;
}
EOF
rm -f /etc/nginx/sites-enabled/fleet-tls.conf
ln -s /etc/nginx/sites-available/fleet-tls.conf /etc/nginx/sites-enabled/fleet-tls.conf
nginx -t

